const input = $input.all();
const digits = v => String(v ?? '').replace(/\D/g, '');
const normalizePhone = v => {
  let p = digits(v);
  if (p.length === 10 || p.length === 11) p = '55' + p;
  return p;
};
const norm = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const pending = new Set(['', 'pendente']);
const rows = input.map((item, index) => {
  const r = item.json;
  return {...r, nome: String(r.Nome ?? ''), telefone: String(r.Telefone ?? '').replace(/^'+/, '').trim(),
    telefone_limpo: normalizePhone(r.Telefone), status: norm(r.Status ?? r.status),
    empresa: [r.Bairro, [r.Cidade, r.UF].filter(Boolean).join('/')].filter(Boolean).join(', '),
    mensagem_enviada: r['Mensagem Enviada'] ?? '', data_envio: r['Data de Envio'] ?? '',
    row_number: Number(r.row_number) || null, _input: index};
});
const hasHistory = r => {
  const m = norm(r.mensagem_enviada);
  return Boolean(r.data_envio) || !['', 'nao', 'false'].includes(m);
};
const blocked = new Set(rows.filter(r => !pending.has(r.status) || hasHistory(r)).map(r => r.telefone_limpo).filter(Boolean));
const seen = new Set();
return rows.map(r => {
  const p = r.telefone_limpo;
  const validFormat = /^55\d{10,11}$/.test(p);
  const elegivel = validFormat && pending.has(r.status) && !blocked.has(p) && !seen.has(p);
  if (elegivel) seen.add(p);
  const index = r._input; delete r._input;
  return {json: {...r, elegivel}, pairedItem: {item: index}};
});

const original = $('Loop Leads (um por vez)1').item.json;
const response = $input.first().json;
let value = response.body ?? response;
if (!Array.isArray(value)) value = value.data ?? value.result ?? value;
const item = Array.isArray(value) ? value[0] : value;
if (!item || ![true, false, 'true', 'false'].includes(item.exists)) {
  throw new Error('Resposta inesperada da Evolution na validação. O lead não foi marcado como inválido. Confira a saída HTTP.');
}
return [{json: {...original, numero_valido: item.exists === true || item.exists === 'true', jid: item.jid ?? null}, pairedItem: {item: 0}}];

