const lead = $('Número Válido?1').item.json;
let out = $json.output ?? $json.text ?? $json;
if (typeof out === 'string') {
  const text = out.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try { out = JSON.parse(text); } catch { throw new Error('A IA não retornou um objeto JSON com mensagem. Nenhum envio foi realizado.'); }
}
if (typeof out?.mensagem !== 'string' || !out.mensagem.trim()) {
  throw new Error('Mensagem da IA ausente ou vazia. Nenhum envio foi realizado.');
}
return {json: {...lead, mensagem_final: out.mensagem.trim(), data_envio: new Date().toISOString()}};

const rows = $input.all().map(i=>i.json).filter(r=>r.resultado!=='vazio');
const selection = $('Selecionar Lote da Pesquisa').first().json;
const errors = rows.filter(r=>r.callback_ok===false);
return [{json:{terminalStatus:errors.length?'completed_with_errors':'completed',stopAcknowledged:true,
summary:{selected:selection.elegiveis,processed:rows.length,sent:rows.filter(r=>r.status_planilha==='enviado').length,invalid:rows.filter(r=>r.status_planilha==='número inválido').length,skipped:rows.filter(r=>r.resultado==='ignorado').length,excludedBeforeSend:selection.excluidosAntesDoEnvio,callbackErrors:errors.length},
receipts:errors.map(r=>r.callback_payload).filter(Boolean),issues:errors.map(r=>({lead_key:r.lead_key,message:r.callback_erro}))}}];

const payload = $('Confirmar Aceite da Evolution').item.json.callback_payload;
const response = $input.first().json;
const body = response.body ?? response;
const ok = !response.error && Number(response.statusCode ?? 200)<400 && body.success === true && body.searchId === payload.searchId && body.automationRunId === payload.automationRunId && String(body.executionId) === payload.executionId && body.lead_key === payload.lead_key && body.persistedStatus === 'enviado';
return [{json:{resultado:'processado',lead_key:payload.lead_key,telefone:payload.telefone,status_planilha:'enviado',callback_ok:ok,callback_erro:ok?null:String(body.reason??body.message??response.error?.message??'Callback sem confirmação do escopo/status').slice(0,1000),callback_payload:payload},pairedItem:{item:0}}];

const lead = $('Número Válido?1').item.json;
const ctx = $('Contexto da Pesquisa').first().json;
const response = $json;
const body = response.body ?? response;
const failed = Boolean(response.error) || Number(response.statusCode ?? 200) >= 400 || body?.success !== true || body.searchId !== ctx.searchId || body.automationRunId !== ctx.automationRunId || String(body.executionId) !== ctx.executionId || body.lead_key !== lead['Lead Key'] || body.persistedStatus !== 'número inválido';
const detail = String(response.error?.message ?? response.error ?? body?.message ?? body?.error ?? 'Callback sem success=true').slice(0,1000);
const payload = {searchId:ctx.searchId, automationRunId:ctx.automationRunId, executionId:ctx.executionId,
  lead_key:lead['Lead Key'], telefone:lead.telefone, status:'número inválido', mensagem_enviada:'número inválido'==='enviado'};
if ('número inválido' === 'enviado') {payload.data_envio=lead.data_envio; payload.messageText=lead.mensagem_final;}
return {json:{resultado:'processado', lead_key:lead['Lead Key'], telefone:lead.telefone, status_planilha:'número inválido',
  callback_ok:!failed, callback_erro:failed?detail:null, callback_payload:payload}};

// Classificação local pelo Website. Não consulta nem altera a API do ScanRadar.
// Categorias inconclusivas ficam para revisão; domínios desconhecidos válidos são tratados como site próprio.
const categorias = ['Sem link', 'Só WhatsApp', 'Só Instagram', 'Link de bio', 'Rede social',
  'Página em plataforma', 'Link encurtado', 'Não identificado', 'Site próprio'];
const norm = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const revisao = new Set(['Site próprio', 'Link encurtado', 'Não identificado']);
const grupos = [
  ['Só WhatsApp', ['wa.me', 'whatsapp.com']],
  ['Só Instagram', ['instagram.com', 'instagr.am']],
  ['Link de bio', ['linktr.ee', 'bio.site', 'beacons.ai', 'bio.link', 'lnk.bio', 'taplink.cc', 'taplink.at', 'tap.bio', 'campsite.bio', 'linkin.bio', 'msha.ke']],
  ['Rede social', ['facebook.com', 'fb.com', 'fb.me', 'tiktok.com', 'linkedin.com', 'youtube.com', 'youtu.be', 'twitter.com', 'x.com', 'pinterest.com', 'threads.net', 'threads.com']],
  ['Página em plataforma', ['mercadolivre.com.br', 'mercadolivre.com', 'mercadolibre.com', 'elo7.com.br', 'shopee.com.br', 'ifood.com.br', 'doctoralia.com.br', 'getninjas.com.br', 'apontador.com.br']],
  ['Link encurtado', ['bit.ly', 'tinyurl.com', 't.co', 'goo.gl', 'shorturl.at', 'cutt.ly', 'is.gd', 'rebrand.ly', 'encurtador.com.br', 'rb.gy', 't.ly']]
];
// Domínios abaixo podem hospedar um site completo; não liberá-los automaticamente.
const hospedagem = ['wixsite.com', 'wordpress.com', 'webflow.io', 'github.io', 'netlify.app', 'vercel.app', 'carrd.co', 'notion.site'];
const pertence = (host, domain) => host === domain || host.endsWith('.' + domain);
function classificar(value) {
  if (value == null || value === '') return {categoria: 'Sem link', dominio: ''};
  if (typeof value !== 'string') return {categoria: 'Não identificado', dominio: ''};
  let url = value.replace(/^'+/, '').trim();
  if (!url) return {categoria: 'Sem link', dominio: ''};
  if (/\s/.test(url) || url.includes('\\')) return {categoria: 'Não identificado', dominio: ''};
  if (/^[a-z][a-z0-9+.-]*:/i.test(url) && !/^https?:\/\//i.test(url)) {
    return {categoria: 'Não identificado', dominio: ''};
  }
  url = url.replace(/^https?:\/\//i, '').replace(/^\/\//, '');
  const authority = url.split(/[/?#]/)[0];
  if (authority.includes('@')) return {categoria: 'Não identificado', dominio: ''};
  const host = authority.replace(/:\d{1,5}$/, '').replace(/\.$/, '').toLowerCase();
  const labels = host.split('.');
  const valid = labels.length >= 2 && host.length <= 253
    && labels.every(l => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(l))
    && /^(?:[a-z]{2,63}|xn--[a-z0-9-]+)$/i.test(labels[labels.length-1]);
  if (!valid) return {categoria: 'Não identificado', dominio: host};
  for (const [categoria, domains] of grupos) {
    if (domains.some(d => pertence(host, d))) return {categoria, dominio: host};
  }
  if (host === 'sites.google.com' || hospedagem.some(d => pertence(host, d))) {
    return {categoria: 'Não identificado', dominio: host};
  }
  return {categoria: 'Site próprio', dominio: host};
}
const items = $input.all();
const classified = items.map((item, index) => {
  const r = item.json;
  const inferred = classificar(r.Website);
  // Opcional: aceita a coluna com o rótulo informado pelo app, caso ela seja adicionada no futuro.
  const rawLabel = r['Presença Digital'] ?? r['Presenca Digital'];
  const supplied = rawLabel == null || String(rawLabel).trim() === '' ? null
    : categorias.find(c => norm(c) === norm(rawLabel)) ?? 'Não identificado';
  // Evidência de revisão tem prioridade, inclusive quando a coluna diverge do link.
  const category = supplied && revisao.has(supplied) ? supplied
    : revisao.has(inferred.categoria) ? inferred.categoria
    : supplied ?? inferred.categoria;
  return {json: {...r, presenca_digital: category, dominio_identificado: inferred.dominio,
    analise_manual: revisao.has(category),
    motivo_analise: revisao.has(category) ? 'Presença digital: ' + category : ''},
    pairedItem: {item: index}};
});
// Um mesmo telefone não pode escapar pelo registro duplicado que tem Website vazio.
const blocked = new Set(classified.filter(i => i.json.analise_manual)
  .map(i => i.json.telefone_limpo).filter(Boolean));
return classified.map(item => {
  const r = item.json;
  if (!r.analise_manual && r.telefone_limpo && blocked.has(r.telefone_limpo)) {
    r.analise_manual = true;
    r.motivo_analise = 'Outra linha com este telefone exige análise manual da presença digital.';
  }
  r.elegivel = r.elegivel === true && !r.analise_manual;
  return item;
});

const body = $json.body;
const validUUID = v => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
if (!body || !validUUID(body.searchId) || !validUUID(body.automationRunId)) {
  throw new Error('Envie searchId e automationRunId válidos pelo backend autenticado do app.');
}
return {json: {searchId: body.searchId.toLowerCase(), automationRunId: body.automationRunId.toLowerCase(), executionId: String($execution.id)}};

const request = $('Validar Solicitação do Botão').first().json;
const rawReply = $input.first().json;
const reply = rawReply.body ?? rawReply;
if (reply.accepted === false) return [{json: {...request, accepted: false, reason: String(reply.reason ?? 'Execução não autorizada')}}];
if (reply.accepted !== true || reply.searchId !== request.searchId || reply.automationRunId !== request.automationRunId || String(reply.executionId) !== request.executionId) {
  throw new Error('Autorização do app ausente ou não corresponde a esta execução.');
}
if (reply.protocolVersion !== 3) throw new Error('Atualize o backend ScanRadar para o protocolo 3 antes de iniciar envios.');
const tab = reply.prospection;
if (!tab || tab.schemaVersion !== 2 || tab.ready !== true || tab.spreadsheetId !== '1rsDDI26rMRg_1qeTh7t7IGHwsKwymBUgUCYS2_tsvPQ'
  || !Number.isInteger(tab.sheetId) || tab.sheetId < 0
  || typeof tab.sheetName !== 'string' || !tab.sheetName.trim()
  || !Array.isArray(tab.eligibleLeadKeys) || !tab.eligibleLeadKeys.every(k => typeof k === 'string' && k.length > 0)
  || new Set(tab.eligibleLeadKeys).size !== tab.eligibleLeadKeys.length
  || tab.eligibleCount !== tab.eligibleLeadKeys.length) {
  throw new Error('Aba individual inválida ou não preparada. A aba geral Leads nunca será usada como alternativa.');
}
return [{json: {...request, accepted: true, prospection: tab,
  offerDescription: String(reply.offerDescription || 'Criação de sites e agentes de automação para empresas.')}}];

const ctx = $('Contexto da Pesquisa').first().json;
const allowed = new Set(ctx.prospection.eligibleLeadKeys);
const seen = new Set();
const rows = [];
for (const [index, item] of $input.all().entries()) {
  const r = item.json;
  if (!Object.entries(r).some(([k,v]) => k !== 'row_number' && v != null && String(v).trim() !== '')) continue;
  const key = String(r['Lead Key'] ?? '');
  if (r['Search ID'] !== ctx.searchId || !key || !allowed.has(key) || seen.has(key)) {
    throw new Error('Linha de outra pesquisa, Lead Key não autorizado ou duplicado. Execução interrompida antes de enviar.');
  }
  seen.add(key);
  rows.push({json:r, pairedItem:{item:index}});
}
return rows.length ? rows : [{json:{__empty:true}, pairedItem:{item:0}}];

const rows = $input.all().map(i => i.json).filter(r => !r.__empty);
const candidates = rows.filter(r => r.elegivel === true);
return [{json:{candidates, lidos:rows.length, elegiveis:candidates.length,
  excluidosAntesDoEnvio:rows.length-candidates.length}}];

const lead = $('Loop Leads (um por vez)1').item.json;
const ctx = $('Contexto da Pesquisa').first().json;
const raw = $input.first().json;
const r = raw.body ?? raw;
if (r.protocolVersion !== 3 || r.searchId !== ctx.searchId || r.automationRunId !== ctx.automationRunId || String(r.executionId) !== ctx.executionId || typeof r.allowed !== 'boolean' || !['continue','stop'].includes(r.directive)) throw new Error('Reserva sem confirmação válida do app.');
if (r.directive === 'stop' && !['cancelling','cancelled'].includes(r.state)) throw new Error('Controle de cancelamento inválido.');
if (r.directive === 'continue' && r.state !== 'running') throw new Error('Reserva fora de rodada ativa.');
return [{json:{...lead,reserva_permitida:r.allowed && r.directive==='continue',stop_requested:r.directive==='stop',motivo_reserva:String(r.reason??'')},pairedItem:{item:0}}];

const row = $input.first().json;
const lead = $('Loop Leads (um por vez)1').item.json;
if (row['Lead Key'] !== lead['Lead Key'] || row.Status !== 'enviado') {
  throw new Error('A atualização da linha na aba individual não foi confirmada. Confira a planilha antes de repetir a execução.');
}
return [{json:row,pairedItem:{item:0}}];

const row = $input.first().json;
const lead = $('Loop Leads (um por vez)1').item.json;
if (row['Lead Key'] !== lead['Lead Key'] || row.Status !== 'número inválido') {
  throw new Error('A atualização da linha na aba individual não foi confirmada. Confira a planilha antes de repetir a execução.');
}
return [{json:row,pairedItem:{item:0}}];

const error = $input.first().json;
const detail = String(error.callback_erro ?? error.error?.message ?? error.error ?? error.message ?? 'Falha durante a prospecção').slice(0,1500);
let receipt = error.callback_payload;
if (!receipt) {try {receipt=$('Confirmar Aceite da Evolution').item.json.callback_payload;} catch {}}
return [{json:{terminalStatus:'failed',summary:null,receipts:receipt?[receipt]:[],issues:[{message:detail,lead_key:receipt?.lead_key??null}],message:detail,stopAcknowledged:true}}];

const request = $('Validar Solicitação do Botão').first().json;
const result = $input.first().json;
return [{json:{action:'finish',protocolVersion:3,...request,status:result.terminalStatus,stopAcknowledged:result.stopAcknowledged===true,summary:result.summary??null,receipts:result.receipts??[],issues:result.issues??[],message:result.message??null}}];

const result = $('Preparar Conclusão da Execução').first().json;
const raw = $input.first().json;
const reply = raw.body ?? raw;
const original = String(result.message ?? result.issues?.[0]?.message ?? '').slice(0,1500);
const invalid = [];
if (reply.success !== true) invalid.push('success diferente de true');
if (reply.protocolVersion !== 3) invalid.push('protocolVersion ausente ou diferente de 3');
if (reply.automationRunId !== result.automationRunId) invalid.push('automationRunId divergente');
if (!['completed','completed_with_errors','failed','cancelled'].includes(reply.state)) invalid.push('state ausente ou não terminal');
if (invalid.length) throw new Error('Resposta de finish incompatível: '+invalid.join('; ')+'. Confira o backend publicado do app. Não liberar a trava automaticamente.'+(original?' Falha anterior: '+original:''));
if (!['completed','cancelled'].includes(reply.state)) throw new Error('Fluxo encerrado com falha/pendências.'+(original?' Causa: '+original:' Consulte a rodada no app.')+' Não reenvie contatos incertos.');
return [{json:{...result,state:reply.state,confirmed:true}}];

// Use o domínio PUBLICADO do ScanRadar. Não é a URL do n8n.
const appBaseUrl = "https://scanradar.netlify.app";
if (appBaseUrl.endsWith('.invalid')) throw new Error('Configure o domínio publicado do ScanRadar antes de executar.');
if (!/^https:\/\/[^/?#]+$/.test(appBaseUrl)) throw new Error('Configure somente a origem HTTPS publicada do app, sem barra final.');
return [{json:{...$input.first().json, appBaseUrl}}];

const ctx = $('Contexto da Pesquisa').first().json;
const raw = $input.first().json;
const r = raw.body ?? raw;
if (r.protocolVersion !== 3 || r.searchId !== ctx.searchId || r.automationRunId !== ctx.automationRunId || String(r.executionId) !== ctx.executionId || !['continue','stop'].includes(r.directive)) throw new Error('Resposta de controle inválida. Nenhum próximo contato será enviado.');
if (r.directive === 'continue' && r.state !== 'running') throw new Error('Estado incompatível com continuação.');
if (r.directive === 'stop' && !['cancelling','cancelled'].includes(r.state)) throw new Error('Rodada encerrada ou fora do escopo.');
return [{json:{...$('Loop Leads (um por vez)1').item.json, stop_requested:r.directive==='stop'},pairedItem:{item:0}}];

const ctx = $('Contexto da Pesquisa').first().json;
const lead = $('Montar Mensagem Final1').item.json;
const raw = $input.first().json;
const r = raw.body ?? raw;
if (r.protocolVersion !== 3 || r.searchId !== ctx.searchId || r.automationRunId !== ctx.automationRunId || String(r.executionId) !== ctx.executionId || typeof r.allowed !== 'boolean') throw new Error('Início do envio não autorizado pelo app.');
if (r.directive === 'stop' && r.allowed === false && ['cancelling','cancelled'].includes(r.state)) return [{json:{...lead,stop_requested:true},pairedItem:{item:0}}];
if (r.directive !== 'continue' || r.state !== 'running' || r.allowed !== true || r.lead_key !== lead['Lead Key'] || r.attemptKey !== ctx.executionId+':'+lead['Lead Key']) throw new Error('Permissão de envio ausente ou divergente.');
return [{json:{...lead,stop_requested:false},pairedItem:{item:0}}];

const lead = $('Montar Mensagem Final1').item.json;
const ctx = $('Contexto da Pesquisa').first().json;
const response = $input.first().json;
const body = response.body ?? response;
const msg = body.data ?? body;
const id = msg.key?.id;
if (response.error || Number(response.statusCode ?? 200)>=400 || typeof id !== 'string' || !id.trim() || msg.key?.fromMe !== true || ['ERROR','FAILED'].includes(String(msg.status).toUpperCase())) throw new Error('Evolution não confirmou o aceite com key.id/fromMe. Resultado incerto: não reenviar automaticamente.');
const callback_payload = {searchId:ctx.searchId,automationRunId:ctx.automationRunId,executionId:ctx.executionId,lead_key:lead['Lead Key'],telefone:lead.telefone_limpo,status:'enviado',mensagem_enviada:true,data_envio:new Date().toISOString(),messageText:lead.mensagem_final,messageId:id};
return [{json:{...lead,callback_payload},pairedItem:{item:0}}];
